/// and modifier or declaration keywords (`export default function`, `@observable readonly`).
fn documents_what_follows(between: &str) -> bool {
    const KEYWORDS: &[&str] = &[
        "export",
        "default",
        "declare",
        "async",
        "abstract",
        "public",
        "private",
        "protected",
        "readonly",
        "static",
        "override",
        "accessor",
        "const",
        "let",
        "var",
        "function",
        "class",
        "interface",
        "type",
        "enum",
        "namespace",
        "module",
